mapper.select:
SELECT category, SUM(amount) as total_amount, COUNT(*) as count
FROM `transaction`
WHERE wallet_id = #{walletId}
  AND DATE_FORMAT(txn_date, '%Y-%m') = #{month}
  AND txn_type = 'PAYMENT'
GROUP BY category

SELECT t.category, SUM(t.amount) as total_amount, COUNT(*) as count FROM `transaction` t LEFT JOIN bucket b ON t.bucket_id = b.bucket_id WHERE t.wallet_id = #{walletId} AND t.txn_type = 'PAYMENT'
AND b.pet_id = #{petId}
GROUP BY t.category
